    /* ================= Theme (Light / Dark / System) ================= */
    var THEMES = ['light', 'dark', 'system'];
    var THEME_LABELS = { light: '\u2600 Light', dark: '\u263E Dark', system: '\u25D0 Auto' };
    function currentTheme() {
      var t = null;
      try { t = localStorage.getItem('nssTheme'); } catch (e) { }
      return THEMES.indexOf(t) >= 0 ? t : 'system';
    }
    function applyTheme() {
      document.documentElement.setAttribute('data-theme', currentTheme());
      var b = document.getElementById('themeBtn');
      if (b) { b.textContent = THEME_LABELS[currentTheme()]; }
    }
    function cycleTheme() {
      var i = THEMES.indexOf(currentTheme());
      var next = THEMES[(i + 1) % THEMES.length];
      try { localStorage.setItem('nssTheme', next); } catch (e) { }
      applyTheme();
    }
    applyTheme();

    (function () {
      var toast = document.getElementById('welcomeToast');
      if (!toast) return;
      function isWindowView() {
        return window.innerWidth > 1024 && !('ontouchstart' in window);
      }
      function showToast() {
        toast.classList.add('show');
        setTimeout(function () {
          toast.classList.remove('show');
        }, 2000);
      }
      if (isWindowView()) return;
      if (document.readyState === 'complete') { setTimeout(showToast, 300); }
      else { window.addEventListener('load', function () { setTimeout(showToast, 300); }); }
    })();

    renderActivities();
    render();
  